import json, numpy as np, collections
recs=[json.loads(l) for l in open('vectors/eval_records.jsonl')]
metrics=json.load(open('vectors/recorded_metrics.json'))
errors=collections.defaultdict(list)
for r in recs:
 z=np.array(r['logits']); y=np.array(r['labels']); n,v=z.shape; eps=r['label_smoothing']; valid=np.flatnonzero(y!=-100)
 s=z-z.max(1,keepdims=True); lp=s-np.log(np.exp(s).sum(1,keepdims=True))
 h=np.zeros(n); h[valid]=-(1-eps)*lp[valid,y[valid]]
 first_ignored=next((i for i in range(n) if y[i]==-100),n)
 masks={'all':np.arange(n),'valid':valid,'span':np.arange(valid[0],valid[-1]+1) if len(valid) else np.array([],int),'prefix_to_last':np.arange(valid[-1]+1) if len(valid) else np.array([],int),'leading_valid_run':np.arange(first_ignored)}
 for form,scale in [('first',eps),('second',eps/v)]:
  terms=h-scale*lp.mean(1)
  for name,inds in masks.items():
   value=terms[inds].sum()/(len(inds) if r['reduction']=='mean' and len(inds) else 1)
   errors[(r['count_policy'],form,name)].append(abs(value-metrics[r['id']]))
for key, vals in sorted(errors.items()):
 print(*key,'matches',sum(x<1e-9 for x in vals),'max_abs_error',max(vals))
PY","max_output_tokens":4000}));

